function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 200000) return 'word needs 1 to 200,000 letters.';
  if (!/^[a-zA-Z]+$/.test(word)) return 'word may contain only English letters.';
  return null;
}

