function numberOfSpecialChars(word) {
  const lastLower = new Map();
  const firstUpper = new Map();
  for (let i = 0; i < word.length; i++) {
    const ch = word[i];
    const letter = ch.toLowerCase();
    if (ch === letter) {
      lastLower.set(letter, i);
    } else if (!firstUpper.has(letter)) {
      firstUpper.set(letter, i);
    }
  }
  let count = 0;
  for (const [letter, last] of lastLower) {
    if (firstUpper.has(letter) && last < firstUpper.get(letter)) {
      count++;
    }
  }
  return count;
}

