function numberOfSpecialChars(word) {
  // Check the definition directly: every lowercase position must be before every uppercase position.
  let total = 0;
  for (let c = 0; c < 26; c++) {
    const lower = String.fromCharCode(97 + c), upper = String.fromCharCode(65 + c);
    const lows = [], ups = [];
    for (let i = 0; i < word.length; i++) {
      if (word[i] === lower) lows.push(i);
      if (word[i] === upper) ups.push(i);
    }
    if (!lows.length || !ups.length) continue;
    let ok = true;
    for (const a of lows) for (const b of ups) if (a > b) ok = false;
    if (ok) total++;
  }
  return total;
}

