function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const k = size === 'large' ? 26 : 1 + Math.floor(rand() * 4);
  // Each letter switches from mostly lowercase to mostly uppercase at its own point; noise flips the case sometimes.
  const split = Array.from({ length: k }, () => Math.floor(rand() * (n + 1)));
  const noise = size === 'large' ? (rand() < 0.5 ? 0.0005 : 0.01) : (rand() < 0.5 ? 0 : 0.3);
  let word = '';
  for (let i = 0; i < n; i++) {
    const c = Math.floor(rand() * k);
    let upper = i >= split[c];
    if (rand() < noise) upper = !upper;
    word += String.fromCharCode((upper ? 65 : 97) + c);
  }
  return [word];
}
